import { createMemo, ParentComponent, useContext } from "solid-js";

import { AudioContext, compileAudioRules, type AudioRule } from "#core/ui-next/services/audio-support.js";

interface AudioContextProviderProps {
	segment?: string;
	vars?: Record<string, string>;

	/**
	 * If not provided, will inherit rules from the parent context.
	 * If there is no parent context, this will use the 'global' rules provided by the modding framework.
	 */
	rules?: AudioRule[];
}

export const AudioContextProvider: ParentComponent<AudioContextProviderProps> = (props) => {
	const parent = useContext(AudioContext);

	const currentPath = createMemo(() => [parent.path(), props.segment].filter((p) => p).join("/"));

	const currentVars = createMemo(() => {
		return { ...parent.vars(), ...props.vars };
	});

	// Only compile if rules are provided (at the root), otherwise inherit tree
	const currentTree = createMemo(() => (props.rules ? compileAudioRules(props.rules) : parent.tree()));

	return (
		<AudioContext.Provider
			value={{
				path: currentPath,
				vars: currentVars,
				tree: currentTree,
			}}
		>
			{props.children}
		</AudioContext.Provider>
	);
};
